);
var stress = relation({}, instances_stress);

// smokes/1: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var stage_smokes = function(rels) {
  var smokes = rels[0];
  var instances_smokes = [].concat(
    // smokes(X) :- stress(X).
    (function() {
      return _.flatten(map(function(e1) {
        var X = e1.t[0];
        return [['smokes', [X], e1.v]];
      }, _.values(stress)));
    })(),
    // smokes(X) :- friend(X,Y), influences(Y,X), smokes(Y).
    (function() {
      return _.flatten(map(function(e1) {
        var X = e1.t[0];
        var Y = e1.t[1];
        return _.flatten(map(function(e2) {
          return _.flatten(map(function(e3) {
            return [['smokes', [X], and([e1.v, e2.v, e3.v])]];
          }, probe(smokes, [Y])));
        }, probe(influences, [Y, X])));
      }, _.values(friend)));
    })()
  );
  var next_smokes = relation({}, instances_smokes);
  return [next_smokes];
};
var stages_smokes = function(rels, stage, before) {
  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_smokes(stage_smokes(rels), stage + 1, size) : rels;
};
var rels_smokes = stages_smokes([{}], 0, -1);
var smokes = rels_smokes[0];

