  friend_facts_1 := [1000000, 1000000, 1000000, 1000011, 1000011, 1000011, 1000013, 1000013, 1000013, 1000014, 1000014, 1000014, 1000015, 1000015, 1000015, 1000016, 1000016, 1000016, 1000017, 1000017, 1000017, 1000018, 1000018, 1000018, 1000019, 1000019, 1000019, 1000001, 1000001, 1000001, 1000002, 1000002, 1000002, 1000003, 1000003, 1000003, 1000004, 1000004, 1000004, 1000005, 1000005, 1000005, 1000006, 1000006, 1000006, 1000007, 1000007, 1000007, 1000008, 1000008, 1000008, 1000009, 1000009, 1000009, 1000010, 1000010, 1000010, 1000012, 1000012, 1000012]: ℤ[];
