              v26 := x21 && x23 && x25;
              f27 := false;
              for k28 in [0..next_smokes_h.length) {
                if next_smokes_1[k28] == X { next_smokes_h[k28] = next_smokes_h[k28] || v26; f27 = true; }
              }
              if !f27 { next_smokes_1 = next_smokes_1 ~ [X]; next_smokes_h = next_smokes_h ~ [v26]; }
            }
          }
        }
      }
    }
    smokes_1 = next_smokes_1;
    smokes_h = next_smokes_h;
    stage13 = stage13 + 1;
  }

  q29 := false;
  for q29_k in [0..smokes_h.length) { if smokes_1[q29_k] == 1000000 { q29 = smokes_h[q29_k]; } }
  q30 := false;
  for q30_k in [0..smokes_h.length) { if smokes_1[q30_k] == 1000002 { q30 = smokes_h[q30_k]; } }
  q31 := false;
  for q31_k in [0..smokes_h.length) { if smokes_1[q31_k] == 1000003 { q31 = smokes_h[q31_k]; } }
  q32 := false;
  for q32_k in [0..smokes_h.length) { if smokes_1[q32_k] == 1000004 { q32 = smokes_h[q32_k]; } }
  q33 := false;
  for q33_k in [0..smokes_h.length) { if smokes_1[q33_k] == 1000005 { q33 = smokes_h[q33_k]; } }
  q34 := false;
  for q34_k in [0..smokes_h.length) { if smokes_1[q34_k] == 1000006 { q34 = smokes_h[q34_k]; } }
  q35 := false;
  for q35_k in [0..smokes_h.length) { if smokes_1[q35_k] == 1000007 { q35 = smokes_h[q35_k]; } }
  q36 := false;
  for q36_k in [0..smokes_h.length) { if smokes_1[q36_k] == 1000008 { q36 = smokes_h[q36_k]; } }
  q37 := false;
  for q37_k in [0..smokes_h.length) { if smokes_1[q37_k] == 1000009 { q37 = smokes_h[q37_k]; } }
  q38 := false;
  for q38_k in [0..smokes_h.length) { if smokes_1[q38_k] == 1000001 { q38 = smokes_h[q38_k]; } }
  queries := [q29, q30, q31, q32, q33, q34, q35, q36, q37, q38];
  return queries[0];
}

