  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_smokes(stage_smokes(rels), stage + 1, size) : rels;
};
var rels_smokes = stages_smokes([{}], 0, -1);
var smokes = rels_smokes[0];

// component 0 bool
// component 1 bool
// component 2 bool
// component 3 bool
// component 4 bool
// component 5 bool
// component 6 bool
// component 7 bool
// component 8 bool
// component 9 bool
// component 10 bool
// component 11 bool
// component 12 bool
// component 13 bool
// component 14 bool
// component 15 bool
// component 16 bool
// component 17 bool
// component 18 bool
// component 19 bool
var model = function() {
  return [holds(smokes, ['p1'])(),
          holds(smokes, ['p2'])(),
          holds(smokes, ['p3'])(),
          holds(smokes, ['p4'])(),
          holds(smokes, ['p5'])(),
          holds(smokes, ['p6'])(),
          holds(smokes, ['p7'])(),
          holds(smokes, ['p8'])(),
          holds(smokes, ['p9'])(),
          holds(smokes, ['p10'])(),
          holds(smokes, ['p11'])(),
          holds(smokes, ['p12'])(),
          holds(smokes, ['p13'])(),
          holds(smokes, ['p14'])(),
          holds(smokes, ['p15'])(),
          holds(smokes, ['p16'])(),
          holds(smokes, ['p17'])(),
          holds(smokes, ['p18'])(),
          holds(smokes, ['p19'])(),
          holds(smokes, ['p20'])()];
};
Infer({method: 'enumerate'}, model);

