def main() {
  // the symbols as numbers: p1 1000000, p10 1000001, p11 1000002, p12 1000003, p13 1000004, p14 1000005, p15 1000006, p2 1000007, p3 1000008, p4 1000009, p5 1000010, p6 1000011, p7 1000012, p8 1000013, p9 1000014
