  friend_1 := friend_facts_1;
  friend_2 := friend_facts_2;
  friend_h := friend_facts_h;

  influences_1 := []: ℤ[];
  influences_2 := []: ℤ[];
  influences_h := []: 𝔹[];
  // 0.2::influences(X,Y) :- friend(X,Y).
  for k1 in [0..friend_h.length) {
    X := friend_1[k1];
    Y := friend_2[k1];
    x2 := friend_h[k1];
    c3 := flip(0.2);
    v4 := x2 && c3;
    f5 := false;
    for k6 in [0..influences_h.length) {
