  q34 := false;
  for q34_k in [0..smokes_h.length) { if smokes_1[q34_k] == 1000011 { q34 = smokes_h[q34_k]; } }
  q35 := false;
  for q35_k in [0..smokes_h.length) { if smokes_1[q35_k] == 1000012 { q35 = smokes_h[q35_k]; } }
  q36 := false;
  for q36_k in [0..smokes_h.length) { if smokes_1[q36_k] == 1000013 { q36 = smokes_h[q36_k]; } }
  q37 := false;
  for q37_k in [0..smokes_h.length) { if smokes_1[q37_k] == 1000014 { q37 = smokes_h[q37_k]; } }
  q38 := false;
  for q38_k in [0..smokes_h.length) { if smokes_1[q38_k] == 1000001 { q38 = smokes_h[q38_k]; } }
  q39 := false;
  for q39_k in [0..smokes_h.length) { if smokes_1[q39_k] == 1000002 { q39 = smokes_h[q39_k]; } }
  q40 := false;
  for q40_k in [0..smokes_h.length) { if smokes_1[q40_k] == 1000003 { q40 = smokes_h[q40_k]; } }
  q41 := false;
  for q41_k in [0..smokes_h.length) { if smokes_1[q41_k] == 1000004 { q41 = smokes_h[q41_k]; } }
  q42 := false;
  for q42_k in [0..smokes_h.length) { if smokes_1[q42_k] == 1000005 { q42 = smokes_h[q42_k]; } }
  q43 := false;
